<script setup>
import {computed} from 'vue';
import {IONS,SALTS} from '../water-chemistry';
const props=defineProps({snapshot:Object,actual:Object});
const result=computed(()=>props.actual?.result||props.snapshot?.planned_result);
const fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3});
</script>
<template><section v-if="snapshot" class="water-summary"><div class="water-summary-head"><div><small>{{ actual?'按实际投加量计算':'计划水质方案' }}</small><strong>{{ snapshot.source?.name }}</strong><p>原水检测 {{ snapshot.source?.measured_on || '配方手动填写' }} · 目标 {{ snapshot.target?.name }}</p></div><b>{{ fmt(result?.volume_l) }} L</b></div><p v-if="snapshot.override_note" class="water-note">原水修改依据：{{ snapshot.override_note }}</p><table><thead><tr><th>调节物</th><th>计划用量</th><th v-if="actual">实际用量</th><th v-if="actual">原料批次</th></tr></thead><tbody><tr v-for="(salt,key) in SALTS" :key="key"><td>{{ salt.name }}<small>{{ salt.formula }} · 纯度 {{ snapshot.recipe_stage?.additions?.[key]?.purity??100 }}%</small></td><td>{{ fmt(snapshot.recipe_stage?.additions?.[key]?.amount||0) }} g</td><td v-if="actual">{{ fmt(actual.stage?.additions?.[key]?.amount||0) }} g</td><td v-if="actual">{{ actual.lots?.[key] || '—' }}</td></tr><tr><td>乳酸<small>{{ snapshot.recipe_stage?.acid?.concentration??88 }}% · {{ snapshot.recipe_stage?.acid?.density??1.21 }} g/mL</small></td><td>{{ fmt(snapshot.recipe_stage?.acid?.amount_ml||0) }} mL</td><td v-if="actual">{{ fmt(actual.stage?.acid?.amount_ml||0) }} mL</td><td v-if="actual">—</td></tr></tbody></table><div v-if="result" class="water-summary-ions"><div v-for="(label,key) in IONS" :key="key"><small>{{ label }}</small><strong>{{ fmt(result.ions[key]) }} <em>mg/L</em></strong></div></div><p v-if="actual?.measured_ph!=null" class="water-ph">调节后水实测 pH：<strong>{{ actual.measured_ph }}</strong></p><p class="water-note">离子值为计算结果，不代表离子检测报告；水 pH 与糖化醪 pH 分开记录。</p><p v-for="warning in result?.warnings||[]" :key="warning" class="water-note">{{ warning }}</p></section></template>
